// Main header
#include "Native_ThreadSimple.h"

// Thread header
#include "Native_ThreadData.h"

// Native header
#include "Native_Mutex.h"
#include "Native_Lock.h"
#include "Native_ScopedMutex.h"
#include "Native_GlobalMacro.h"

#define NANO_SECOND_MULTIPLIER  1000000 // 1 millisecond = 1,000,000 Nanoseconds

using namespace NativeT;
NATIVE_Sint32_t ThreadSimple::m_thread_number = 0;
Condition ThreadSimple::m_num_cond;

uint64_t gettid() {
    pthread_t ptid = pthread_self();
    uint64_t threadId = 0;
    memcpy(&threadId, &ptid, std::min(sizeof(threadId), sizeof(ptid)));
    return threadId;
}

/**************************************************************************
 ** NativeT::ThreadSimple
 *************************************************************************/

ThreadSimple::ThreadSimple(NATIVE_Sint32_t p_runWait)
    : m_cond            ( PTHREAD_COND_INITIALIZER )
    , m_stopCondReturn  ( 0 )
    , running           ( false )
	, finished          ( false )
	, terminated        ( false )
    , isInFinish        ( false )
	, exited            ( false )
    , m_StartEvent      ( false )
    , m_returnCode      ( -1 )
    , m_runWait         ( p_runWait )
    , m_priority        ( ThreadSimple::InheritPriority )
	, m_bDeleteSelf     ( false )
	, m_waiters         ( 0 )
	, m_threadID        ( zero_ID() )
    , m_SuspendFlag     ( 0 )
{
    // Condition
    pthread_cond_init( &m_cond, NULL );
    pthread_mutex_init( &m_SuspendMutex, NULL );
    pthread_cond_init( &m_ResumeCond, NULL );
}

/* -------------------------------------------------------------------
* Initialize thread object. Do not start the object's thread execution.
* ------------------------------------------------------------------- */

void ThreadSimple::DeleteSelfAfterRun( void )
{
	m_bDeleteSelf = true;
}

NATIVE_Sint32_t ThreadSimple::number_user_threads( void ) 
{
	return m_thread_number;
}

/* -------------------------------------------------------------------
 * Stop this object's thread execution (if any) immediately.
 * ------------------------------------------------------------------- */

ThreadSimple::~ThreadSimple() 
{
    // Stop the thread
    Stop();
    // Release ID
	m_threadID = zero_ID();
    // Release condition
    pthread_cond_destroy( &m_cond );
    pthread_mutex_destroy( &m_SuspendMutex );
    pthread_cond_destroy( &m_ResumeCond);
}

/* -------------------------------------------------------------------
 * Initialize thread object. Do not start the object's thread execution.
 * ------------------------------------------------------------------- */




/* -------------------------------------------------------------------
 * Start the object's thread execution. Increments thread
 * count, spawns new thread, and stores thread m_threadID.
 * ------------------------------------------------------------------- */

void ThreadSimple::Start( void ) 
{
    if( m_SuspendFlag ==0 && equal_ID(m_threadID, zero_ID()) )
	{
        // Increment thread count
        m_num_cond.Lock();
        m_thread_number++;
        m_num_cond.Unlock();
        

        
        // Spawn the thread
        if( int retval = pthread_create( &m_threadID, NULL, Run_Wrapper, this) )
        {
            std::cerr << "Failed to spawn thread: " << retval << std::endl;
            NATIVE_ASSERT_UNREACHABLE(0, "ThreadSimple::Start( void ): Failed to spawn thread");
        }
    }
    else
    {
        pthread_mutex_lock(&m_SuspendMutex);
        m_SuspendFlag = 0;
        pthread_cond_signal(&m_ResumeCond);
        pthread_mutex_unlock(&m_SuspendMutex);
    }
    
} // end Start

void ThreadSimple::Pause( void )
{
    pthread_mutex_lock(&m_SuspendMutex);
    m_SuspendFlag = 1;
    pthread_mutex_unlock(&m_SuspendMutex);
} // end Pause

