void ThreadSimple::detach( void )
{
     pthread_detach( m_threadID );
     
     m_threadID = 0;
}

/* -------------------------------------------------------------------
 * Low level function which starts a new thread, called by
 * Start(). The argument should be a pointer to a ThreadSimple object.
 * Calls the virtual Run() function for that object.
 * Upon completing, decrements thread count and resets thread m_threadID.
 * If the object is deallocated immediately after calling Start(),
 * such as an object created on the stack that has since gone
 * out-of-scope, this will obviously fail.
 * [static]
 * ------------------------------------------------------------------- */

void* ThreadSimple::Run_Wrapper( void* paramPtr ) 
{
#ifndef NDEBUG
    NATIVE_ASSERT( paramPtr != NULL );
#endif
    
    // Grab thread pointer
    ThreadSimple* objectPtr = (ThreadSimple*) paramPtr;
    
    // Set thread state to started
    objectPtr->setStarted();

    // Run thread (pure virtual function)
    objectPtr->Run();

    // Reset thread state
	objectPtr->resetStarted();

    // Auto delete
    if ( objectPtr->m_bDeleteSelf ) {
        DELETE_PTR( objectPtr );
    }

    return NULL;
} // end run_wrapper

/* -------------------------------------------------------------------
 * Wait for this object's thread execution (if any) to complete.
 * ------------------------------------------------------------------- */

void ThreadSimple::Join( void ) 
{
    if( !equal_ID(m_threadID, zero_ID()) )
    {
        if( m_threadID != pthread_self() )
        {
            // Wait timed out
            if( m_stopCondReturn == ETIMEDOUT )
            {
                // Try to forcefully stop it at a cancellation point
                // Use exit() if called from within this thread
                if( pthread_equal(pthread_self(), m_threadID) ) {
                    pthread_exit( NULL );
                }
                // Use cancel() if called from a different thread
                else {
                    int e = pthread_cancel( m_threadID );
                    if( e != 0 ) {
                        NATIVE_ASSERT_COND(0, "ThreadSimple::Join( void )", "pthread_cancel call failed \n");
                    }
                }
            } // m_stopCondReturn == ETIMEDOUT
            
            // Join thread
            else
            {
                void * state;
                int e = pthread_join( m_threadID, &state );
                if( e != 0 ) {
                    switch(e)
                    {
                        case EDEADLK:
                            NATIVE_ASSERT_COND(0, "ThreadSimple::Join( void )", "pthread_join call failed with return EDEADLK \n");
                            break;
                        case EINVAL:
                            NATIVE_ASSERT_COND(0, "ThreadSimple::Join( void )", "pthread_join call failed with return EINVAL \n");
                            break;
                        case ESRCH:
                            NATIVE_ASSERT_COND(0, "ThreadSimple::Join( void )", "pthread_join call failed with return ESRCH \n");
                            break;
                    }
                }
            }
        }// m_threadID != pthread_self()
        
        else {
            NATIVE_ASSERT_COND(0, "ThreadSimple::Join( void )", "pthread_join called from thread itself \n");
        }
        
    } //! equal_ID( m_threadID, zero_ID())
    
    
    // Decrement thread count
    m_num_cond.Lock();
    m_thread_number--;
    m_num_cond.Signal();
    m_num_cond.Unlock();
    
    // Set thread id to zero
    m_threadID = zero_ID();
    
    
    
//	if ( !equal_ID(m_threadID, zero_ID()) )
//	{
//        void* stat;
//        if( m_threadID != pthread_self() )
//        {
//            int r = pthread_join( m_threadID , &stat );
//            if( r != 0 ) {
//                NATIVE_ASSERT_COND(0, "ThreadSimple::Join( void )", "pthread_join call failed \n");
//            }
//            
//            m_threadID = zero_ID();
//        }
//        else {
//            NATIVE_ASSERT_COND(0, "ThreadSimple::Join( void )", "pthread_join called from thread itself \n");
//        }
//	} //! equal_ID( m_threadID, zero_ID()) 
} // end Join

/* -------------------------------------------------------------------
 * Wait for all thread object's execution to complete. Depends on the
 * thread count being accurate and the threads sending a condition
 * signal when they terminate.
 * [static]
 * ------------------------------------------------------------------- */

void ThreadSimple::join_all( void ) 
{
    m_num_cond.Lock();
    while ( m_thread_number > 0 ) 
	{
        m_num_cond.Wait();
    }
    m_num_cond.Unlock();
} // end join_all


/* -------------------------------------------------------------------
 * Return the current thread's Id.
 * [static]
 * ------------------------------------------------------------------- */
nthread_t ThreadSimple::current_thread_ID()
{
    return pthread_self();
}


/* -------------------------------------------------------------------
 * Compare the thread m_threadID's (inLeft == inRight); return true if they
 * are equal. On some OS's nthread_t is a struct so == will not work.
 * TODO use pthread_equal. Any Win32 equivalent??
 * [static]
 * ------------------------------------------------------------------- */

bool ThreadSimple::equal_ID( nthread_t inLeft, nthread_t inRight ) 
{
    return(memcmp( &inLeft, &inRight, sizeof(inLeft)) == 0);
}

/* -------------------------------------------------------------------
 * Return a zero'd out thread m_threadID. On some OS's nthread_t is a struct
 * so == 0 will not work.
 * [static]
 * ------------------------------------------------------------------- */

nthread_t ThreadSimple::zero_ID( void ) 
{
    nthread_t a;
    memset( &a, 0, sizeof(a));
    return a;
}

/* -------------------------------------------------------------------
 * set a thread to be daemon, so joinall won't wait on it
 * this simply decrements the thread count that joinall uses,
 * which is not a thorough solution, but works for the moment
 * ------------------------------------------------------------------- */

void ThreadSimple::SetDaemon( void ) 
{
    m_num_cond.Lock();
    m_thread_number--;
    m_num_cond.Signal();
    m_num_cond.Unlock();
}

 
    
bool ThreadSimple::setPriority(priorities p)
  {
      bool result = true;
    
      struct sched_param param;
      // Convert
    switch (m_priority) 
	{
        case IdlePriority:
            param.sched_priority = 5;
            break;

        case LowestPriority:
            param.sched_priority = 0;
            break;

        case LowPriority:
            param.sched_priority = 3;
            break;

        case NormalPriority:
            param.sched_priority = 5;
            break;
            
        case HighPriority:
            param.sched_priority = 7;
            break;

        case HighestPriority:
            param.sched_priority = 9;
            break;

        case TimeCriticalPriority:
            param.sched_priority = 10;
            break;

        case InheritPriority:
        default:
            struct sched_param param;
            int policy = SCHED_OTHER;   
                pthread_getschedparam(m_threadID, &policy, &param);
                param.sched_priority = param.sched_priority;
        break;
    }

      result = pthread_setschedparam(m_threadID, SCHED_OTHER, &param) == 0;
      
      return result;
  }

  /**
   * Set the m_priority for the native thread if supported by the 
   * system.
   *
   * @param ThreadSimple::PRIORITY& current m_priority
   * @return bool false if unsuccessful
   */

bool ThreadSimple::getPriority(priorities& prio) 
{

    bool result = true;
    
    struct sched_param param;
    int policy = SCHED_OTHER;
    
    if((result = (pthread_getschedparam(m_threadID, &policy, &param) == 0)))
    {

        // Convert to one of the PRIORITY values
        switch(param.sched_priority) 
        {
          
            case 9 : 
                prio =  IdlePriority;
                break;

            case 0 :
                prio = LowestPriority;
                break;

            case 3 :
                prio = LowPriority ;
                break;

            case 10 :
                prio = NormalPriority;
                break;

            case 12 :
                prio = HighPriority;
                break;

            case 15 :
                prio = HighestPriority ;
                break;

            case 20 :
                prio = TimeCriticalPriority;
                break;
            default:
                // Convert to one of the PRIORITY values
                if(param.sched_priority < 10)
                    prio = LowPriority;
                else if(param.sched_priority == 10)
                    prio = NormalPriority;
                else
                    prio = TimeCriticalPriority;
        }
    }
  return result;
}


/**
 * Detect OS at runtime and attempt to locate the SwitchToThread
 * function, which will assist in making the spin lock implementation
 * which use ThreadOps::yield() a bit fairer.
 */

bool ThreadSimple::yield() 
{

  static YieldOps yielder;

  yielder();

  return true;

}



///////////////////////////////////////////////////////////////////////////////////////////////////
//      RUNNING STATE MANAGEMENT
///////////////////////////////////////////////////////////////////////////////////////////////////

//=================================================================================================
bool ThreadSimple::Running(void)
{
    pthread_mutex_lock(&m_SuspendMutex);
    while (m_SuspendFlag != 0) pthread_cond_wait(&m_ResumeCond, &m_SuspendMutex);
    pthread_mutex_unlock(&m_SuspendMutex);
    
	u_sleep( (NATIVE_Uint32_t)m_runWait );
    return m_StartEvent;
}

//=================================================================================================
void ThreadSimple::resetStarted( void )
{
    m_StartEvent = false;
    
    mutex.Lock();
    int ret = pthread_cond_signal( &m_cond );
    if( ret!= 0 )
    {
        ERR_PRINT_STRING( "cond failed" );
    }
    mutex.Unlock();
}

//=================================================================================================
bool ThreadSimple::Started( void )
{
    return m_StartEvent;
}

//=================================================================================================
void ThreadSimple::setStarted( void )
{
    m_StartEvent = true;
}



///////////////////////////////////////////////////////////////////////////////////////////////////
//      SLEEP
///////////////////////////////////////////////////////////////////////////////////////////////////

//=================================================================================================
void ThreadSimple::m_sleep (const NATIVE_Sint32_t millisecs)
{
    u_sleep((NATIVE_Uint32_t)millisecs);
}

//=================================================================================================
void ThreadSimple::u_sleep(NATIVE_Uint32_t iters)
{
	const NATIVE_Uint64_t interval_ms = NANO_SECOND_MULTIPLIER * iters;

    u_sleep(interval_ms);
}

//=================================================================================================
void ThreadSimple::u_sleep(NATIVE_Uint64_t ticks)
{
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = ticks*1000; // Apparently this needs 1000 time more ticks than Win32
    nanosleep(& ts, NULL);
    
}



